import Blockly from 'blockly/core';
import 'blockly/blocks';
import { pythonGenerator } from 'blockly/python';

Blockly.Blocks['array_create'] = {
  init: function() {
    this.appendDummyInput()
        .appendField("[")
        .appendField(new Blockly.FieldTextInput("1, 2, 3"), "VALUES") // Nhập từ bàn phím
        .appendField("]");
    this.setOutput(true, "Array");
    this.setColour(230); // Màu tím
    this.setTooltip("Enter values separated by commas to create an array.");
  }
};

// Python Generator
pythonGenerator.forBlock['array_create'] = function(block) {
  const values = block.getFieldValue('VALUES').split(',').map(v => v.trim()); // Tách từng phần tử
  return [`[${values.join(', ')}]`, pythonGenerator.ORDER_ATOMIC];
};

Blockly.Blocks['get_value_by_index'] = {
  init: function() {
    this.appendDummyInput()
        .appendField("Get value from")
        .appendField(new Blockly.FieldVariable("array"), "ARRAY"); // Chọn biến từ dropdown
    this.appendValueInput("INDEX") // Dùng Value Input để có thể kết nối khối số
        .setCheck("Number")
        .appendField("[");
    this.appendDummyInput()
        .appendField("]");
    this.setOutput(true, "Number");
    this.setInputsInline(true);
    this.setColour(230);
    this.setTooltip("Get a value from an array by index.");
  }
};

// Python Generator
pythonGenerator.forBlock['get_value_by_index'] = function(block) {
  const arrayName = block.getFieldValue('ARRAY'); // Lấy tên biến mảng
  const index = pythonGenerator.valueToCode(block, 'INDEX', pythonGenerator.ORDER_ATOMIC) || "0"; // Lấy giá trị index
  return [`${arrayName}[${index}]`, pythonGenerator.ORDER_ATOMIC];
};
